const r = $input.first().json.r || {};
const entrada = $('Z-API chamou (mensagem recebida)').first().json.body || {};

// 'equipe' vai para o agente; 'sair' e 'boas-vindas' já vêm com a frase
// pronta do banco e só precisam ser entregues; 'ignorar' morre aqui.
return [{
  json: {
    tipo: r.tipo || 'ignorar',
    ehEquipe: r.tipo === 'equipe',
    temResposta: r.tipo === 'sair' || r.tipo === 'boas-vindas',
    phone: entrada.phone,
    texto: (entrada.text || {}).message || '',
    quem: r.nome || entrada.senderName || null,
    papel: r.papel || null,
    fala: r.fala || null,
  }
}];
